6:  test("person contact", { tag: '@functionality' }, async ({ browser }) => {
11:    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "contact": " Ada@X "}));
12:    expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "contact": "ada@x"})).toBeNull();
13:    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "contact": ""}));
14:    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "contact": "cam@x"}));
